import{H as e,V as t,et as n,j as r}from"./chunks/framework.DSSJFrgb.js";var i=JSON.parse(`{"title":"BYOK 构建踩坑记录","description":"记录在开发AI应用时搭建BYOK时遇到的问题和解决方案","frontmatter":{"title":"BYOK 构建踩坑记录","date":"2026-08-07T00:00:00.000Z","description":"记录在开发AI应用时搭建BYOK时遇到的问题和解决方案","tags":["GoogleADK","SpringAI","大模型"]},"headers":[],"relativePath":"tech/ai/BYOK踩坑记录.md","filePath":"tech/ai/BYOK踩坑记录.md"}`),a={name:`tech/ai/BYOK踩坑记录.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="byok-构建踩坑记录" tabindex="-1">BYOK 构建踩坑记录 <a class="header-anchor" href="#byok-构建踩坑记录" aria-label="Permalink to “BYOK 构建踩坑记录”">​</a></h1><h2 id="环境基础" tabindex="-1">环境基础 <a class="header-anchor" href="#环境基础" aria-label="Permalink to “环境基础”">​</a></h2><p>SpringBoot + GoogleADK 1.7.1 + Spring AI 2.0.0</p><h2 id="坑-adk-携带工具调用时-openaichatmodel-抛-classcastexception" tabindex="-1">坑：ADK 携带工具调用时 OpenAiChatModel 抛 ClassCastException <a class="header-anchor" href="#坑-adk-携带工具调用时-openaichatmodel-抛-classcastexception" aria-label="Permalink to “坑：ADK 携带工具调用时 OpenAiChatModel 抛 ClassCastException”">​</a></h2><p><strong>背景</strong>：BYOK（Bring Your Own Key）模式下，通过 <code>DynamicChatModel</code> 动态包装 <code>OpenAiChatModel</code>，交给 Google ADK 使用。 依赖版本：<code>google-adk-spring-ai 1.7.1</code> + <code>spring-ai-openai 2.0.0</code>。</p><p><strong>现象</strong>：Agent 只要配置了工具（MCP / function-calls），首次调用大模型就抛异常；不配工具则正常。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>java.lang.ClassCastException: class org.springframework.ai.model.tool.DefaultToolCallingChatOptions</span></span>
<span class="line"><span>  cannot be cast to class org.springframework.ai.openai.OpenAiChatOptions</span></span>
<span class="line"><span>  at org.springframework.ai.openai.OpenAiChatModel.createRequest(...)</span></span></code></pre></div><p><strong>根因</strong>：两个框架的契约缺口，三个环节叠加导致：</p><ol><li>ADK 构造 Prompt 前先调 <code>chatModel.getOptions()</code> 作为 options 底座（<code>SpringAI.resolveDefaultOptions</code>）， 传给 <code>MessageConverter.buildChatOptions(llmRequest, modelDefaultOptions)</code>。该方法有三个分支： <ul><li>无工具且无 ADK 生成配置 → 返回 null，由 Spring AI 兜底注入模型默认 options；</li><li>首选路径：底座 <code>instanceof ToolCallingChatOptions</code> → <code>mutate()</code> 派生并保留厂商类型；</li><li>回退路径：用通用 <code>ToolCallingChatOptions.builder()</code> 构造，产物是 <code>DefaultToolCallingChatOptions</code>； ADK 源码注释明确说明首选路径就是为规避 Spring AI OpenAI 2.0.0 对 Prompt.getOptions() 的强转而设计；</li></ul></li><li><code>ChatModel.getOptions()</code> 的接口默认实现返回通用的 <code>DefaultChatOptions</code>（非 ToolCallingChatOptions）， 而 <code>DynamicChatModel</code> 作为包装类当时未覆写该方法，导致 ADK 拿不到底层的 <code>OpenAiChatOptions</code>， 命中上述回退路径（携带工具时必触发）；</li><li><code>OpenAiChatModel.createRequest</code> 对 options 直接强转 <code>(OpenAiChatOptions) prompt.getOptions()</code>，无任何类型判断。</li></ol><p>直接把 <code>OpenAiChatModel</code> 交给 ADK 不会遇到此问题，因为它的 <code>getOptions()</code> 返回自身的 <code>OpenAiChatOptions</code>， <code>buildChatOptions</code> 走首选路径 mutate 派生，产物仍是厂商类型；问题只出在 <code>DynamicChatModel</code> 这层包装把底层 options 对 ADK 隐藏了。</p><p><strong>修复</strong>（均在 <code>DynamicChatModel</code>）：</p><ol><li>覆写 <code>getOptions()</code> 透传底层 <code>OpenAiChatModel</code> 的 options——这是根治，让 <code>buildChatOptions</code> 走 ADK 设计的首选路径， 基于 <code>OpenAiChatOptions</code> mutate 派生，自动保留 model/apiKey/baseUrl 等厂商配置；</li><li>另保留防御性归一化方法 <code>normalizePrompt</code>（当前未接入 call/stream 主链路）：options 为 null 或已是 <code>OpenAiChatOptions</code> 时原样透传，否则基于模型默认 options 调 <code>mutate()</code> 派生新对象再合并 <code>toolCallbacks</code>、 <code>toolContext</code>；若未来有调用方绕过 ADK 直接传入通用类型 options，可在 call/stream 中重新接入。</li></ol><p><strong>实现注意点</strong>：</p><ol><li><strong>包装类必须透传 getOptions()</strong>：任何包装 <code>ChatModel</code> 的装饰器/代理，若不透传 <code>getOptions()</code>， ADK 就会因拿到接口默认的通用 options 而回退到通用类型，这是本坑的最隐蔽之处；</li><li><strong>工具回调不能丢</strong>：转换时如果只搬 model/apiKey/baseUrl 而落下 <code>toolCallbacks</code>，请求会变成不带工具的调用， function call 静默失效且不报错，比 ClassCastException 更难排查；</li><li><strong>createRequest 只从 Prompt options 读 model</strong>：转换后的 options 必须携带 model 字段，否则请求缺 model 报错； 这也是推荐「以默认 options 为底 mutate()」而非「new 一份空 options 只填三要素」的原因——前者自动继承所有默认参数， 后者将来给默认 options 加 temperature、maxTokens 等配置时容易漏搬；</li><li><code>DefaultToolCallingChatOptions</code> 上不存在 model/apiKey/baseUrl 字段，无法就地修改，只能生成新对象。</li></ol>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};